import React, { useState, useEffect, useRef } from "react";
import "./App.css";
import botIcon from "./bot-icon.png";
import Navbar from "./components/Navbar"; // Import Navbar

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [activePage, setActivePage] = useState("chat"); // State for Navbar Navigation
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = async () => {
    if (input.trim() === "") return;

    setMessages([...messages, { text: input, type: "user" }]);
    setInput("");

    try {
      const response = await fetch("http://localhost:5000/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: input }), // ✅ Corrected API request
      });

      const data = await response.json();

      if (response.ok) {
        setMessages((prevMessages) => [
          ...prevMessages,
          { text: data.response, type: "bot" }, // ✅ Fixed AI response
        ]);
      } else {
        throw new Error(data.error || "AI response failed");
      }
    } catch (error) {
      console.error("Error fetching response:", error);
      setMessages((prevMessages) => [
        ...prevMessages,
        { text: "⚠️ AI is not responding. Try again later.", type: "bot" },
      ]);
    }
  };

  return (
    <div className="app-container">
      {/* Navbar */}
      <Navbar setActivePage={setActivePage} />

      {/* Page Content */}
      <div className="content">
        {activePage === "chat" && (
          <div className="chatbox">
            <div className="messages">
              {messages.map((msg, index) => (
                <div key={index} className={`message-container ${msg.type}`}>
                  {msg.type === "bot" && <img src={botIcon} alt="Bot" className="bot-icon" />}
                  <div className={`message ${msg.type}`}>
                    <p>{msg.text}</p>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
            <div className="input-area">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask me anything..."
              />
              <button onClick={handleSendMessage}>➤</button>
            </div>
          </div>
        )}

        {activePage === "progress" && (
          <div className="progress">
            <h2>📊 Your Learning Progress</h2>
            <p>Track your AI learning progress here!</p>
          </div>
        )}

        {activePage === "settings" && (
          <div className="settings">
            <h2>⚙️ Settings</h2>
            <p>Customize your AI Tutor experience.</p>
          </div>
        )}
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 PAT  | </p>
      </footer>
    </div>
  );
};

export default App;
